      '<div class="grid two-col fullplan-lower"><section class="card fullplan-panel"><div class="section-head"><div><h2>\u8d39\u7528\u6e05\u5355</h2><p>\u53c2\u8003\u4ef7\u548c\u5b9e\u9645\u91d1\u989d\u5206\u5f00\u663e\u793a</p></div><button class="btn small" data-page="expenses">\u7ba1\u7406\u8d39\u7528</button></div><div class="fullplan-rows">'+(expenseHtml||'<div class="fullplan-empty">\u8fd8\u6ca1\u6709\u8d39\u7528\u8bb0\u5f55\u3002</div>')+'</div></section>'+
      '<section class="card fullplan-panel"><div class="section-head"><div><h2>\u51fa\u884c\u51c6\u5907</h2><p>'+done+' / '+total+' \u9879\u5df2\u5b8c\u6210</p></div><button class="btn small" data-page="prepare">\u7ba1\u7406\u51c6\u5907</button></div><div class="fullplan-detail"><span>\u4f4f\u5bbf</span><strong>'+esc(t.hotel||"\u5f85\u8865\u5145")+'</strong><span>\u7d27\u6025\u8054\u7cfb\u4eba</span><strong>'+esc(maskedContact)+'</strong><span>\u9884\u7ea6\u4e8b\u9879</span><strong>'+esc(t.reservation||"\u6682\u65e0\u586b\u5199")+'</strong><span>\u5929\u6c14\u67e5\u8be2</span><strong><a href="'+esc(t.weather||"https://www.weather.com.cn/")+'" target="_blank" rel="noopener">\u6253\u5f00\u5929\u6c14\u67e5\u8be2 ↗</a></strong></div><div class="fullplan-checklist">'+(checklist||'<div class="fullplan-empty">\u51c6\u5907\u6e05\u5355\u6682\u65e0\u4e8b\u9879\u3002</div>')+'</div><div class="fullplan-people"><h3>\u540c\u884c\u8005\u9700\u6c42</h3>'+(companions||'<div class="fullplan-empty">\u6682\u65e0\u540c\u884c\u8005\u4fe1\u606f\u3002</div>')+'</div></section></div>'+
      '<div class="notice fullplan-notice">'+icon("info-circle")+'<span>\u6bcf\u65e5\u8def\u7ebf\u3001\u8ddd\u79bb\u548c\u65f6\u957f\u9700\u4ee5\u9ad8\u5fb7\u5b9e\u9645\u67e5\u8be2\u7ed3\u679c\u4e3a\u51c6\u3002\u5f53\u524d demo \u672a\u63a5\u5165\u9ad8\u5fb7\u8def\u7ebf\u670d\u52a1\uff0c\u4e0d\u4f1a\u5728\u8fd9\u91cc\u8865\u9020\u8def\u7ebf\u6216\u4ea4\u901a\u65f6\u957f\u3002\u65b0\u589e\u548c\u7f16\u8f91\u7684\u5185\u5bb9\u4ec5\u5728\u672c\u6b21\u6253\u5f00\u671f\u95f4\u6709\u6548\u3002</span></div>';
