  function prepareView(){var t=activeTrip();if(!t)return pageIntro("出发清单","创建旅行后，集中查看清单、预约和同行者需求。",'','GET READY')+'<div class="empty">先创建一趟旅行。</div>';var done=t.checklist.filter(function(x){return x.done}).length,checks=t.checklist.map(function(x,i){return '<label class="check-row '+(x.done?"done":"")+'"><input type="checkbox" data-action="check-item" data-index="'+i+'" '+(x.done?"checked":"")+'><span><strong>'+esc(x.title)+'</strong><small>'+(x.done?"已完成":"出发前核对")+'</small></span><button class="icon-btn" type="button" aria-label="删除事项" data-action="delete-check" data-index="'+i+'">'+icon("x")+'</button></label>'}).join("");var people=t.companions.map(function(p){return '<div class="people-row"><span class="people-avatar">'+esc(p.name.slice(0,1))+'</span><span><strong>'+esc(p.name)+'</strong><small>'+esc(p.need||"暂无备注")+'</small></span></div>'}).join("");return pageIntro("出发清单","把预约、同行者需要和出发前待办放在一起。",'','READY WHEN YOU ARE')+'<div class="grid two-col"><div><section class="card checklist"><div class="section-head" style="margin:0"><div><h2>准备清单</h2><p>'+done+' / '+t.checklist.length+' 项完成</p></div><button class="icon-btn" aria-label="添加清单事项" data-action="new-check">'+icon("plus")+'</button></div><div class="progress-track"><i style="width:'+(t.checklist.length?Math.round(done/t.checklist.length*100):0)+'%"></i></div><div style="margin-top:9px">'+(checks||'<div class="empty">清单已完成。还想补充什么？</div>')+'</div></section><section class="card form-card" style="margin-top:14px"><h3>住宿与紧急联系人</h3><div class="form-grid"><div class="form-field full"><label>住宿名称 / 地址</label><input data-save="hotel" value="'+esc(t.hotel)+'" placeholder="填写住宿名称和地址"></div><div class="form-field full"><label>紧急联系人（姓名和电话）</label><input data-save="contact" value="'+esc(t.contact)+'" placeholder="出发前补充"></div></div><div style="display:flex;justify-content:flex-end;margin-top:10px">'+btn("保存信息","save-prepare","small","device-floppy")+'</div></section></div><div><section class="card form-card"><div class="section-head" style="margin:0 0 8px"><div><h2>同行者需求</h2><p>饮食偏好与亲子需要</p></div></div><div>'+people+'</div><button class="btn small" style="margin-top:11px" data-action="edit-companions">'+icon("edit")+'编辑同行者</button></section><section class="card form-card" style="margin-top:14px"><h3>预约与天气查询</h3><div class="form-field"><label>预约时间 / 事项</label><textarea data-save="reservation" placeholder="记录已确认的预约或待核实事项">'+esc(t.reservation||"")+'</textarea></div><div class="weather-link" style="margin-top:11px"><span class="weather-icon">☀️</span><span><strong>查看天气预报</strong><small>打开天气查询网站，行前再次确认</small></span><a class="btn small" style="margin-left:auto" href="'+esc(t.weather||"https://www.weather.com.cn/")+'" target="_blank" rel="noopener">查询 ↗</a></div><div style="margin-top:13px">'+btn("保存准备信息","save-prepare","small soft","device-floppy")+'</div></section><div class="notice" style="margin-top:14px">'+icon("info-circle")+'<span>此页面不会发送天气通知或后台提醒。联系人与住宿信息仅在本次打开期间有效。</span></div></div></div>'}
  function render(){var main=document.getElementById("main");if(!state.authenticated){document.body.classList.add("login-screen-active");document.getElementById("sidebar").innerHTML="";document.getElementById("topbar").innerHTML="";document.getElementById("mobile-nav").innerHTML="";main.innerHTML=loginView();document.title="登录 · 途见";return}document.body.classList.remove("login-screen-active");shell();var html=state.page==="trips"?home():state.page==="features"?featureView():state.page==="food"?foodView():state.page==="itinerary"?itineraryView():state.page==="expenses"?expensesView():state.page==="plan"?fullPlanView():prepareView();main.innerHTML='<div class="main-content">'+html+'</div>';document.title=(navItems.find(function(n){return n[0]===state.page})||navItems[0])[1]+" · 途见"}
  function field(label,name,value,type,placeholder,required){return '<div class="form-field"><label>'+label+'</label><input class="input" style="font-size:11px;height:38px" name="'+name+'" type="'+(type||"text")+'" value="'+esc(value||"")+'" placeholder="'+esc(placeholder||"")+'" '+(required?"required":"")+'></div>'}
  function openModal(title,desc,body,submitText,onSubmit,danger){var root=document.getElementById("modal-root");root.innerHTML='<div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><div><h2 id="modal-title">'+esc(title)+'</h2><p>'+esc(desc||"")+'</p></div><button class="modal-x" data-action="close-modal" aria-label="关闭">'+icon("x")+'</button></div><form id="modal-form"><div class="modal-body">'+body+'</div><div class="modal-actions"><button type="button" class="btn" data-action="close-modal">取消</button><button type="submit" class="btn '+(danger?"danger":"primary")+'">'+esc(submitText||"保存")+'</button></div></form></div>';var first=root.querySelector("input,select,textarea,button");if(first)first.focus();root.onclick=function(e){if(e.target===root)closeModal()};root.querySelector("form").onsubmit=function(e){e.preventDefault();var data=Object.fromEntries(new FormData(e.currentTarget).entries());if(onSubmit(data)!==false){closeModal();persist();render()}}}
  function closeModal(){document.getElementById("modal-root").innerHTML=""}
  function tripDialog(t){var editing=!!t;t=t||{cities:[],people:1,budget:"",prefs:""};var body='<div class="form-grid">'+field("旅行名称","name",t.name,"text","例如：周末杭州慢游",true)+field("同行人数","people",t.people,"number","1",true)+field("出发日期","start",t.start,"date","",true)+field("返程日期","end",t.end,"date","",true)+field("目的地城市","cities",(t.cities||[]).join("、"),"text","支持多城市，用顿号分隔",true)+field("旅行预算（元）","budget",t.budget,"number","可留空")+'</div><div class="form-field"><label>节奏、偏好或硬性条件</label><textarea name="prefs" class="input" style="height:auto;min-height:70px;padding:9px 10px" placeholder="例如：每天午休、不吃辣、少换酒店">'+esc(t.prefs||"")+'</textarea></div>';openModal(editing?"编辑旅行":"新建旅行", "填写旅行基本信息，稍后可以继续调整。",body,editing?"保存修改":"创建旅行",function(d){if(d.end<d.start){notify("返程日期不能早于出发日期。");return false}var data={name:d.name.trim(),people:Number(d.people)||1,start:d.start,end:d.end,cities:d.cities.split(/[、,，]/).map(function(x){return x.trim()}).filter(Boolean),budget:Number(d.budget)||0,prefs:d.prefs.trim()};if(editing)Object.assign(t,data);else{data.id="trip-"+Date.now();Object.assign(data,{notes:"",favorites:[],events:[],expenses:[],checklist:[],companions:[],hotel:"",contact:"",reservation:"",weather:"https://www.weather.com.cn/"});state.trips.unshift(data);state.selected=data.id}notify("旅行信息仅在本次打开期间有效。")} )}
  function eventDialog(index){var t=activeTrip(),e=index==null?{day:state.dayIndex||0,time:"09:00",name:"",kind:"景点",address:"",note:"",locked:false}:t.events[index];if(!e)return;var opts=["景点","用餐","住宿","交通","体验","其他"].map(function(c){return '<option '+(e.kind===c?"selected":"")+'>'+c+'</option>'}).join("");var dayOpts=days(t).map(function(d,i){return '<option value="'+i+'" '+(Number(e.day)===i?"selected":"")+'>第 '+(i+1)+' 天 · '+dateText(d.toISOString().slice(0,10))+'</option>'}).join("");var body='<div class="form-grid">'+field("安排名称","name",e.name,"text","例如：西湖散步",true)+field("时间","time",e.time,"time","",true)+'<div class="form-field"><label>安排类型</label><select name="kind" class="select" style="width:100%;height:38px">'+opts+'</select></div><div class="form-field"><label>安排日期</label><select name="day" class="select" style="width:100%;height:38px">'+dayOpts+'</select></div>'+field("地点地址","address",e.address,"text","填写地点或地址")+'<div class="form-field"><label>锁定此安排</label><select name="locked" class="select" style="width:100%;height:38px"><option value="false" '+(!e.locked?"selected":"")+'>不锁定</option><option value="true" '+(e.locked?"selected":"")+'>锁定顺序</option></select></div></div><div class="form-field"><label>备注</label><textarea class="input" style="height:auto;min-height:70px;padding:9px 10px" name="note">'+esc(e.note)+'</textarea></div>';openModal(index==null?"添加行程安排":"编辑行程安排","手动添加地点、日期、时段和备注。",body,index==null?"添加安排":"保存修改",function(d){var item={day:Number(d.day)||0,time:d.time,name:d.name.trim(),kind:d.kind,address:d.address.trim(),note:d.note.trim(),locked:d.locked==="true"};if(index==null)t.events.push(item);else Object.assign(t.events[index],item);state.dayIndex=item.day;notify("行程安排已保存。")})}
  function expenseDialog(index){var t=activeTrip(),e=index==null?{name:"",category:"交通",date:t.start,quantity:1,reference:"",actual:"",link:"",note:""}:t.expenses[index];if(!e)return;var cats=["交通","住宿","门票","餐饮","租车","其他"].map(function(c){return '<option '+(e.category===c?"selected":"")+'>'+c+'</option>'}).join("");var body='<div class="form-grid">'+field("项目名称","name",e.name,"text","例如：酒店住宿",true)+'<div class="form-field"><label>费用类别</label><select class="select" style="width:100%;height:38px" name="category">'+cats+'</select></div>'+field("日期","date",e.date,"date")+field("数量","quantity",e.quantity,"number","1")+field("参考总价（元）","reference",e.reference,"number","不确定可留空")+field("实际总价（元）","actual",e.actual,"number","尚未购买可留空")+field("购买链接","link",e.link,"url","外部商品或服务链接")+'</div><div class="form-field"><label>备注</label><textarea class="input" style="height:auto;min-height:65px;padding:9px 10px" name="note">'+esc(e.note)+'</textarea></div>';openModal(index==null?"添加费用记录":"编辑费用记录","记录项目总价；数量单独记录，实际金额由你手动填写。",body,index==null?"保存记录":"保存修改",function(d){var actual=d.actual.trim()===""?"":Number(d.actual),reference=d.reference.trim()===""?"":Number(d.reference);if((actual!==""&&(!Number.isFinite(actual)||actual<0))||(reference!==""&&(!Number.isFinite(reference)||reference<0))){notify("金额请填写不小于 0 的数字。");return false}var item={name:d.name.trim(),category:d.category,date:d.date,quantity:Math.max(1,Number(d.quantity)||1),reference:reference,actual:actual,link:d.link.trim(),note:d.note.trim()};if(index==null)t.expenses.push(item);else Object.assign(t.expenses[index],item);notify("费用记录已保存。")})}
  function action(target){var el=target.closest("[data-action],[data-page]");if(!el)return;var a=el.dataset.action,page=el.dataset.page,t=activeTrip(),idx=Number(el.dataset.index);if(page){state.page=page;state.filter.search="";render();window.scrollTo(0,0);return}if(!a)return;switch(a){case"close-modal":closeModal();break;case"logout":state.authenticated=false;render();break;case"toggle-password":var passwordInput=document.getElementById("login-password");if(passwordInput){passwordInput.type=passwordInput.type==="password"?"text":"password";el.textContent=passwordInput.type==="password"?"显示":"隐藏";el.setAttribute("aria-label",passwordInput.type==="password"?"显示密码":"隐藏密码")}break;case"new-trip":tripDialog();break;case"edit-trip":tripDialog(state.trips.find(function(x){return x.id===el.dataset.id}));break;case"open-trip":state.selected=el.dataset.id;state.page="itinerary";state.dayIndex=0;persist();render();break;case"delete-trip":var deleting=state.trips.find(function(x){return x.id===el.dataset.id})||t;if(!deleting)return;openModal("删除这趟旅行？","这会从本次打开的演示中删除旅行、行程与费用记录。",'<div class="notice">'+icon("info-circle")+'<span>删除后将无法在本次打开期间恢复；刷新页面会重新载入演示数据。</span></div>',"确认删除",function(){state.trips=state.trips.filter(function(x){return x.id!==deleting.id});state.selected=state.trips[0]?state.trips[0].id:null;state.page="trips";notify("旅行已从本次演示中删除。")},true);break;case"new-event":eventDialog();break;case"edit-event":eventDialog(idx);break;case"delete-event":if(t&&t.events[idx]){t.events.splice(idx,1);persist();render();notify("已删除该安排。")}break;case"toggle-lock":if(t&&t.events[idx]){t.events[idx].locked=!t.events[idx].locked;persist();render();notify(t.events[idx].locked?"已锁定此安排。":"已取消锁定。")}break;case"move-up":case"move-down":if(t&&t.events[idx]&&!t.events[idx].locked){var day=Number(t.events[idx].day),same=t.events.map(function(e,i){return{e:e,i:i}}).filter(function(x){return Number(x.e.day)===day}).sort(function(x,y){return String(x.e.time).localeCompare(String(y.e.time))}),pos=same.findIndex(function(x){return x.i===idx}),other= a==="move-up"?pos-1:pos+1;if(other>=0&&other<same.length&&!same[other].e.locked){var ta=t.events[idx].time;t.events[idx].time=t.events[same[other].i].time;t.events[same[other].i].time=ta;persist();render()}else notify("相邻安排已锁定或已经到达顺序边界。")}else notify("已锁定的安排不能移动。");break;case"select-day":state.dayIndex=Number(el.dataset.day);render();break;case"route-demo":openModal("高德路径规划尚未接入","这里展示的是界面占位，不是实际路线结果。",'<div class="notice">'+icon("info-circle")+'<span>接入高德开放平台后，系统将按你手动排好的当日地点顺序查询路线、距离和时长。当前静态网站没有 API Key，不发起请求，也不会把高德结果写入本地。</span></div>',"知道了",function(){return true});break;case"favorite":case"food-favorite":if(!t)return;var name=el.dataset.name;t.favorites=t.favorites||[];var pos=t.favorites.indexOf(name);if(pos>=0)t.favorites.splice(pos,1);else t.favorites.push(name);persist();render();notify(pos>=0?"已取消收藏。":"已加入收藏。");break;case"feature-filter":state.filter.feature=el.dataset.value;render();break;case"meal-filter":state.filter.meal=el.dataset.value;render();break;case"taste-filter":state.filter.taste=el.dataset.value;render();break;case"new-expense":expenseDialog();break;case"edit-expense":expenseDialog(idx);break;case"delete-expense":if(t){t.expenses.splice(idx,1);persist();render();notify("费用记录已删除。")}break;case"check-item":if(t){t.checklist[idx].done=el.checked;persist();render()}break;case"new-check":openModal("添加准备事项","写下一件出发前要确认的事。",'<div class="form-field"><label>事项</label><input class="input" name="title" required placeholder="例如：确认景点预约时间"></div>',"添加",function(d){if(d.title.trim())t.checklist.push({title:d.title.trim(),done:false});notify("已添加到准备清单。")});break;case"delete-check":if(t){t.checklist.splice(idx,1);persist();render()}break;case"save-prepare":if(t){document.querySelectorAll("[data-save]").forEach(function(input){t[input.dataset.save]=input.value});persist();notify("出行准备信息仅在本次打开期间有效。")}break;case"edit-companions":if(t){var names=t.companions.map(function(x){return x.name+"："+x.need}).join("\n");openModal("同行者饮食与出行需求","每行填写一位同行者，格式为“姓名：需求”。",'<div class="form-field"><textarea class="input" style="height:auto;min-height:120px;padding:10px" name="people">'+esc(names)+'</textarea></div>',"保存需求",function(d){t.companions=d.people.split(/\r?\n/).map(function(line){var p=line.split("：");return{name:(p.shift()||"").trim(),need:p.join("：").trim()}}).filter(function(x){return x.name});notify("同行者需求已保存。")})}break;case"save-trip":break;default:break}}
  document.addEventListener("click",function(e){action(e.target)});
  document.addEventListener("submit",function(e){if(!e.target||e.target.id!=="login-form")return;e.preventDefault();var identity=document.getElementById("login-identity"),password=document.getElementById("login-password"),message=document.getElementById("login-message");if(!identity.value.trim()||!password.value){message.textContent="请填写邮箱或手机号和密码。";return}state.authenticated=true;render();notify("已进入静态演示；身份信息未验证，也不会保存。")});
  document.addEventListener("change",function(e){if(e.target&&e.target.matches&&e.target.matches("[data-city-switch]")){state.filter.city=e.target.value;state.filter.search="";render()}});
